'use strict';
const app=document.querySelector('#app');
const services={wash:{name:'Wash & Detailing',sub:'A little care goes a long way.',icon:'wash-detailing',business:'Shine Studio',service:'Full wash & vacuum',price:'R 330'},repairs:{name:'Repairs & Maintenance',sub:'Keep your car moving.',icon:'repairs-maintenance',business:'Northside Auto',service:'Vehicle service assessment',price:'Quote required'},glass:{name:'Glass Repair & Replacement',sub:'Clear answers for chips and cracks.',icon:'glass-repair',business:'Clearview Glass',service:'Windscreen assessment',price:'Quote required'},tyres:{name:'Tyres & Wheel Alignment',sub:'A smoother, safer drive.',icon:'tyres-alignment',business:'The Wheel Room',service:'Wheel alignment',price:'R 450'}};
const state={service:'wash',location:'Rosebank',outcome:'success'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(route,text,cls='btn')=>`<a class="${cls}" href="#${route}">${text}</a>`;
const crumb=(route='search/'+state.service,text='Back to results')=>`<a class="back" href="#${route}">← ${text}</a>`;
const title=(eyebrow,heading,desc='')=>`<div class="eyebrow">${eyebrow}</div><h1 class="title">${heading}</h1>${desc?`<p class="lead">${desc}</p>`:''}`;
const fields=(label,name,type='text',extra='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${extra}></div>`;
const tabs=()=>`<div class="service-tabs" aria-label="Service categories">${Object.entries(services).map(([id,s])=>link('search/'+id,s.name,'chip'+(id===state.service?' active':''))).join('')}${link('fines','Fines & Vehicle Admin','chip')}</div>`;
const summary=()=>`<aside class="card summary"><span class="eyebrow">Example booking</span><h3>${services[state.service].business}</h3><div><span>Service</span><strong>${services[state.service].service}</strong></div><div><span>Area</span><strong>${esc(state.location)}</strong></div><div><span>Estimated price</span><strong>${services[state.service].price}</strong></div><hr class="rule"><p class="muted small">This is fictional sample data. No reservation has been made.</p></aside>`;
function search(){let s=services[state.service];return `${title('Find a service',s.name,s.sub)}${tabs()}<div class="layout"><div class="stack"><form class="card" id="search-form"><label for="location"><strong>Where do you need a service?</strong></label><p class="muted small">Enter a suburb to explore this fictional example.</p><div class="searchbox"><input name="location" id="location" value="${esc(state.location)}" maxlength="80" required><button class="btn" type="submit">Search nearby →</button></div></form><div class="between"><div><h2>Businesses near ${esc(state.location)}</h2><p class="muted small">Example results · distances are straight-line estimates</p></div><span class="tag gray">1 example</span></div><article class="card"><div class="between"><div class="row"><img class="big-icon" src="/assets/studio/objects/carworx-object-${s.icon}.svg" alt=""><div><span class="tag green">Example listing</span><h2>${s.business}</h2><p class="muted">${esc(state.location)} · 2.4 km away</p></div></div><span class="price">${s.price}</span></div><hr class="rule"><p>${s.service} · Request a time that works for you.</p><div class="bar">${link('listing','View business →')}<span class="small muted">Business accepts before a booking is held</span></div></article><div class="notice blue">Can't find what you're looking for? Search another suburb. This preview uses fictional listings only. <a href="#empty">See a no-results example →</a></div></div>${summary()}</div>`}
function empty(){return `${crumb('search/'+state.service,'Back to results')}${title('Example empty state','No businesses found here.','This example shows what happens when there are no results in the selected area.')}<div class="card"><h2>Try another suburb</h2><p>Searches will not widen without your choice. The real service may offer a way to record demand when no businesses are available.</p>${link('search/'+state.service,'Change search →')}</div>`}
function listing(){let s=services[state.service];return `${crumb()}${title('Example business · '+esc(state.location),s.business,'Straightforward service, with the details in writing.')}<div class="bar"><span class="tag green">Example listing</span><span class="tag gray">2.4 km straight-line</span><span class="tag gray">Fictional business</span></div><div class="layout"><div class="stack"><article class="card"><h2>Services &amp; prices</h2><p class="muted">A business confirms availability before you commit.</p><hr class="rule"><div class="between"><div><h3>${s.service}</h3><p class="muted small">${state.service==='wash'?'Inside and out, with a careful finish.':'The business will review your request and send the details in writing.'}</p></div><strong>${s.price}</strong></div></article><article class="card"><h2>About this business</h2><p>This is a fictional business created to demonstrate the CarworX experience. Opening hours and checks would appear here once available.</p><span class="tag gray">Checks shown as examples only</span></article><article class="card"><h2>What happens next?</h2><p>Send a request. The business reviews it and responds before any slot is held or payment is requested.</p></article></div><aside class="card"><span class="eyebrow">Start a request</span><h2>${s.service}</h2><p class="muted">Choose a preferred date and tell the business what you need.</p>${link('request','Request a booking →')}</aside></div>`}
function request(){return `${crumb('listing','Back to business')}${title('Step 1 of 3','Tell us what you need.','Your request goes to the business for a response. This preview does not send anything.')}<div class="steps"><span class="on">1 Request</span><span>2 Response</span><span>3 Checkout</span></div><div class="layout"><form class="card" id="request-form"><h2>Your request</h2><div class="field"><label for="service-date">Preferred date</label><input type="date" id="service-date" name="date" required></div><div class="field"><label for="time">Preferred time</label><select id="time" name="time"><option>Morning</option><option>Afternoon</option><option>Flexible</option></select></div><div class="field"><label for="details">Anything the business should know?</label><textarea id="details" name="details" placeholder="Describe the service you need. Please do not enter personal information."></textarea></div><div class="notice">Preview only: your details stay in this browser and are not sent.</div><p><button class="btn" type="submit">Preview request →</button></p></form>${summary()}</div>`}
function sent(){return `${crumb('request','Edit request')}${title('Request preview','Your request is ready.','In the real service, the business would review your request and respond.')}<div class="layout"><div class="stack"><div class="notice green"><strong>Simulation only.</strong> No request has been sent and no booking exists.</div><div class="card"><h2>What happens next?</h2><ol class="list"><li>The business reviews the request.</li><li>For repairs, it can send a written quote for your approval.</li><li>After acceptance, a slot may be held while you pay.</li></ol>${link('quote','See example response →')} ${link('search/'+state.service,'Explore more businesses','btn secondary')}</div></div>${summary()}</div>`}
function quote(){return `${crumb('sent','Back to request')}${title('Step 2 of 3','Review the response.','An example of what an accepted request or written quote could look like.')}<div class="steps"><span>1 Request</span><span class="on">2 Response</span><span>3 Checkout</span></div><div class="layout"><div class="stack"><div class="card"><div class="between"><div><span class="tag green">Example accepted request</span><h2>${services[state.service].business}</h2></div><span class="price">${services[state.service].price==='Quote required'?'R 1 240':services[state.service].price}</span></div><p>${services[state.service].service}</p><hr class="rule"><p class="muted">Example quote version 1 · valid for 7 days</p><p>Review the scope and price before approving. If a quote changes, the earlier version cannot be paid.</p><div class="notice blue">This is a simulation. No business has accepted a request or provided a quote.</div><p>${link('checkout','Approve example & continue →')} ${link('sent','Not now','btn secondary')}</p></div><div class="card note"><strong>In writing, every step.</strong><p>Any extra work would need its own change quote.</p></div></div>${summary()}</div>`}
function checkout(){return `${crumb('quote','Back to response')}${title('Step 3 of 3','Review checkout.','A preview of the payment step. No payment details are collected and nothing can be charged.')}<div class="steps"><span>1 Request</span><span>2 Response</span><span class="on">3 Checkout</span></div><div class="layout"><div class="stack"><div class="card"><span class="tag orange">Example · slot held for 15 minutes</span><h2>Ready when you are.</h2><p>In the real service you would pay on the payment partner’s secure page. A booking is confirmed only after the payment partner confirms receipt.</p><div class="notice">If the hold expires, the slot is released. If a payment arrives afterwards, CarworX would help you rebook or get a refund.</div><div class="field"><label for="outcome">Explore a simulated payment result</label><select id="outcome"><option value="success">Successful payment</option><option value="pending">Payment pending</option><option value="failed">Payment failed</option><option value="late">Payment arrives after expiry</option></select></div><button class="btn orange" id="simulate-payment" type="button">Simulate payment result →</button></div></div>${summary()}</div>`}
function result(kind){let messages={success:['Example payment confirmed','In the live service, confirmation follows a verified payment notification.','green'],pending:['Example payment pending','The payment is not confirmed yet. Check its status before trying again.','blue'],failed:['Example payment failed','No payment was confirmed in this simulation. You can return and try another result.',''],late:['Example late payment','The slot has been released. A late successful payment would be reconciled and you would be helped to rebook or receive a refund.','']};let [h,p,c]=messages[kind]||messages.pending;return `${crumb('checkout','Back to checkout')}${title('Simulated result',h,p)}<div class="notice ${c}"><strong>Preview only.</strong> No payment, booking or communication has occurred.</div><div class="bar" style="margin-top:24px">${link('checkout','Try another result','btn secondary')}${link('search/'+state.service,'Explore services →')}</div>`}
function apply(){return `${title('For businesses','Good work deserves<br>to be found.','Show customers what you offer and manage requests in one place. This is a simulated application.')}<div class="layout"><form class="card" id="apply-form"><h2>Tell us about your business</h2><p class="muted small">Use fictional details for this preview. Nothing is submitted.</p>${fields('Business name','business','text','required maxlength="100" placeholder="Example business"')}${fields('Area served','area','text','required maxlength="80" placeholder="Example suburb"')}<div class="field"><label for="category">Main service</label><select id="category" name="category">${Object.values(services).map(s=>`<option>${s.name}</option>`).join('')}</select></div><div class="field"><label for="description">Tell us a little about your business</label><textarea id="description" placeholder="Use fictional details only."></textarea></div><div class="notice blue">A person would review real applications. Mobile businesses’ home bases stay private.</div><p><button class="btn" type="submit">Preview application →</button></p></form><aside class="card note"><strong>Made for your working day.</strong><p>Keep requests, quotes and next steps in one place.</p>${link('dashboard','Explore example dashboard','btn secondary')}</aside></div>`}
function applied(){return `${title('Application preview','Thanks for taking a look.','This is how the next step could appear after an application.')}<div class="notice green"><strong>Simulation only.</strong> Your application was not sent or saved.</div><p class="bar" style="margin-top:24px">${link('dashboard','Explore example dashboard →')}${link('apply','Back to application','btn secondary')}</p>`}
function bookings(){return `${title('Your bookings · example','Your next good drive.','Fictional booking history. No booking or payment exists.')}<div class="stack"><article class="card"><span class="tag green">Confirmed example</span><h2>Full wash &amp; vacuum</h2><p>Shine Studio · Friday, 09:00 · Rosebank</p><p class="muted small">Example booking CW-DEMO-1042 · R 330</p><div class="bar">${link('listing','View business','btn secondary')}${link('result/success','View example confirmation')}</div></article><article class="card"><span class="tag gray">Completed example</span><h2>Wheel alignment</h2><p>The Wheel Room · Last month</p><p class="muted small">Fictional example record. No personal booking information is stored.</p></article><div class="bar">${link('search/wash','Find another service →')}<a class="btn secondary" href="/onboarding/account/index.html?as=driver&tab=profile">Profile and settings</a></div></div>`}
function dashboard(){return `${title('Business workspace · example','Good morning, Bubbleworks.','A fictional dashboard showing how a business could manage its day.')}<div class="bar"><span class="tag orange">Demo workspace</span><span class="muted small">All figures, customers and jobs are fictional.</span></div><div class="bar" style="margin-top:20px"><a class="btn" href="/onboarding/setup/index.html#hub">Finish setup →</a><a class="btn secondary" href="/onboarding/setup/index.html#t-team">Manage team</a><a class="btn secondary" href="/onboarding/account/index.html?as=owner&amp;tab=security">Security</a></div><div class="metric-grid" style="margin-top:24px"><div class="card metric"><span class="eyebrow">Requests this week</span><strong>12</strong><span class="muted small">3 awaiting reply</span></div><div class="card metric"><span class="eyebrow">Paid directly</span><strong>R 3 960</strong><span class="muted small">Example figure</span></div><div class="card metric"><span class="eyebrow">Average reply</span><strong>1h 07</strong><span class="muted small">Example response time</span></div></div><div class="layout"><div class="stack"><section class="card"><div class="between"><h2>Requests to review</h2><span class="tag orange">3 examples</span></div><div class="table-row"><div><strong>Full wash &amp; vacuum</strong><div class="small muted">Thandi M. · Rosebank · Tomorrow</div></div><button class="btn secondary" data-dash="Accepted example request" type="button">Accept</button></div><div class="table-row"><div><strong>Interior detailing</strong><div class="small muted">Pieter K. · Parkhurst · Friday</div></div><button class="btn secondary" data-dash="Example request declined" type="button">Decline</button></div><div id="dash-feedback" class="notice blue hidden" role="status"></div></section><section class="card"><h2>Today’s jobs</h2><div class="table-row"><span>09:00 · Full wash &amp; vacuum</span><span class="tag green">Confirmed example</span></div><div class="table-row"><span>11:30 · Interior detailing</span><span class="tag gray">Awaiting example</span></div></section></div><aside class="card note"><strong>Keep it moving.</strong><p>Respond to requests in time and keep customers informed.</p>${link('apply','View business application','btn secondary')}</aside></div>`}
function fines(){return `${title('Fines & vehicle admin','A fine on the windscreen?','Straight answers, in plain words.')}<div class="layout"><div class="stack"><div class="card"><span class="tag orange">Guidance only</span><h2>Start with the official notice.</h2><p>Check the issuing authority, reference number, due date and instructions printed on your notice. Use the official channel named there to verify your options.</p><p>CarworX does not look up fines in this preview. Do not enter an ID number or payment details here.</p></div><div class="card"><h2>Where to go next</h2><p>For national AARTO information, consult the official AARTO website. For a municipal notice, use the issuing municipality’s official website or contact details on the notice.</p><a class="btn secondary" href="https://www.aarto.gov.za/" target="_blank" rel="noopener noreferrer">Open official AARTO website ↗</a><p class="muted small">Opens an external website. Availability and applicable processes can vary.</p></div></div><aside class="card note"><strong>Keep your details yours.</strong><p>This preview never asks for identity numbers or searches for fines.</p></aside></div>`}
function render(){let [route,arg]=location.hash.slice(1).split('/');if(services[arg]&&route==='search')state.service=arg;let pages={search,empty,listing,request,sent,quote,checkout,result:()=>result(arg),apply,applied,dashboard,bookings,fines};if(route==='apply'){location.replace('/onboarding/phase1/index.html');return}if(route==='applied'){location.replace('/onboarding/phase1/index.html#submitted');return}let view=pages[route]||search;app.innerHTML=`<div class="shell">${view()}</div>`;document.title='CarworX — '+(route==='dashboard'?'Business dashboard':route==='fines'?'Fines guidance':route==='apply'?'For businesses':'Car care, booked properly');document.querySelector('#mobile-nav').hidden=true;document.querySelector('.menu').setAttribute('aria-expanded','false');window.scrollTo(0,0);app.focus({preventScroll:true})}
window.addEventListener('hashchange',render);document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='search-form'){let value=new FormData(e.target).get('location').trim();if(value){state.location=value;render()}}else if(e.target.id==='request-form'){location.hash='sent'}else if(e.target.id==='apply-form'){location.hash='applied'}});document.addEventListener('click',e=>{if(e.target.id==='simulate-payment')location.hash='result/'+document.querySelector('#outcome').value;let b=e.target.closest('[data-dash]');if(b){let out=document.querySelector('#dash-feedback');out.textContent=b.dataset.dash+'. No change was sent or saved.';out.classList.remove('hidden')}if(e.target.closest('.menu')){let menu=document.querySelector('#mobile-nav'),button=document.querySelector('.menu');menu.hidden=!menu.hidden;button.setAttribute('aria-expanded',String(!menu.hidden));button.setAttribute('aria-label',menu.hidden?'Open menu':'Close menu')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('#mobile-nav').hidden){document.querySelector('#mobile-nav').hidden=true;let b=document.querySelector('.menu');b.setAttribute('aria-expanded','false');b.focus()}});render();
